 const faults=mode==='faults'?[{"path":"src/infrastructure/database/event-log.ts","kind":"absent-source-allowed","from":"reportInvalidToConsole: false, requireSourceFiles: true","to":"reportInvalidToConsole: false, requireSourceFiles: false"},{"path":"src/infrastructure/database/event-log.ts","kind":"invalid-record-replay","from":"if (report.invalidEvents.length > 0)","to":"if (false)"},{"path":"src/infrastructure/database/event-log.ts","kind":"void-false-success","from":"if (report.invalidEvents > 0)","to":"if (false)"},{"path":"src/infrastructure/database/event-log.ts","kind":"raw-record-disclosure","from":"line: \"\",","to":"line: report.invalidEvents[0]!.line,"},{"path":"src/presentation/cli/commands/projections.ts","kind":"verify-tolerates-missing-source","from":"await readProjectionEventsWithReport(","to":"await (await import(\"../../../infrastructure/database/event-log.js\")).readMemoryEventsWithReport("}]:[];
 for(const fault of [null,...faults]){
