 }else console.log(JSON.stringify(runs.map(run=>({fault:run.fault,exit:run.exit}))));
 writeFileSync(`.git/q100-admission-${mode}.json`,JSON.stringify({recordedAt:new Date().toISOString(),scope:'Scoped diagnostic; full instrumenter/platform/package/changed-line and independent review acceptance remains open.',runtime:Bun.version,sourceInputs:paths.map(path=>({path,sourceHash:sourceHash(originals.get(path)!)})),runs,measurement,source:readFileSync('.git/q100-admission-diagnostic.ts','utf8')},null,2)+'\n');
}finally{storage.cleanup();}

