import {readFileSync,writeFileSync} from 'node:fs';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
import {discoverInventory} from '../scripts/quality-inventory';
const storage=createOwnedTestDirectory('memory-admission-final-');
try {
 const command=[process.execPath,'test','--timeout','15000','./.git/b11-event-atomicity-probe.test.ts','./.git/b11-combined-projection-admission.test.ts'];
 const child=Bun.spawnSync(command,{env:{...process.env,TEMP:storage.dir,TMP:storage.dir,TMPDIR:storage.dir},stdout:'pipe',stderr:'pipe',timeout:45000});
 const output=new TextDecoder().decode(child.stdout)+new TextDecoder().decode(child.stderr);
 writeFileSync('.git/q100-remaining-red.json',JSON.stringify({command,exit:child.exitCode,output,sourceInputs:discoverInventory(process.cwd()).files.map(f=>({path:f.path,sourceHash:f.sourceHash})),probes:command.slice(4).map(path=>({path,source:readFileSync(path,'utf8')}))},null,2)+'\n');
 if(child.exitCode!==1||!output.includes('2 pass')||!output.includes('1 fail'))throw Error(output);
 const cfg=JSON.parse(readFileSync('.git/q100-admission-tests-tsconfig.json','utf8'));
 cfg.include=cfg.include.filter((p:string)=>!p.includes('/integration/'));
 writeFileSync('.git/q100-admission-focused-tsconfig.json',JSON.stringify(cfg,null,2)+'\n');
 const typeCommand=[process.execPath,'node_modules/typescript/bin/tsc','--project','.git/q100-admission-focused-tsconfig.json'];
 const typed=Bun.spawnSync(typeCommand,{stdout:'pipe',stderr:'pipe',timeout:45000});
 const typeOutput=new TextDecoder().decode(typed.stdout)+new TextDecoder().decode(typed.stderr);
 writeFileSync('.git/q100-admission-focused-types.json',JSON.stringify({command:typeCommand,exit:typed.exitCode,output:typeOutput,config:cfg},null,2)+'\n');
 if(typed.exitCode!==0)throw Error(typeOutput);
 const diagnostics=readFileSync('.git/q100-admission-test-types.txt','utf8');
 const baseline=Bun.spawnSync(['git','show','b2e99bb:tests/integration/infrastructure/database/event-log.test.ts'],{stdout:'pipe',stderr:'pipe'});
 if(baseline.exitCode!==0)throw Error('Missing baseline source');
 const old=new TextDecoder().decode(baseline.stdout),current=readFileSync('tests/integration/infrastructure/database/event-log.test.ts','utf8').split(/\r?\n/);
 const rows=[...diagnostics.matchAll(/event-log.test.ts\((\d+),\d+\): error TS2532:/g)];
 if(rows.length!==34)throw Error('Unexpected existing type error count');
 for(const row of rows)if(!old.includes(current[Number(row[1])-1]!))throw Error('Changed error line');
 console.log('Known late-write defect remains; missing-source readiness repaired. Focused types pass;34 integration diagnostics occur on unchanged baseline lines.');
} finally {storage.cleanup();}
